def link(url, text):
    return f'<a href="{escape(url, quote=True)}">{text}</a>'

def button(url, text, light=False):
    return f'<a class="button{" light" if light else ""}" href="{url}">{text} <span class="arrow" aria-hidden="true">↗</span></a>'

def citation(url, text):
    return f'<p class="source">Source: {link(url,text)}.</p>'

def head(kicker, title, description):
    return f'<section class="page-head wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{description}</p></section>'

def contents(items):
    return '<nav class="contents wrap" aria-label="On this page">'+''.join(link('#'+anchor,label) for anchor,label in items)+'</nav>'

